-- duda_taylor_paciente_full_sqlite.sql
-- Este arquivo contém a criação da tabela Paciente e todas as inserções de dados
-- compatíveis com SQLite.

CREATE TABLE Paciente
(
    CD_Registro INTEGER PRIMARY KEY AUTOINCREMENT,
    CD_Animal_Clinica VARCHAR(20) NULL,
    NM_Animal VARCHAR(50) NULL,
    DS_Especie VARCHAR(30) NULL,
    DS_Raca VARCHAR(50) NULL,
    DS_Sexo VARCHAR(10) NULL,
    DS_Idade_Referencia VARCHAR(50) NULL,
    DS_Chip VARCHAR(30) NULL,
    NR_Peso_Referencia NUMERIC(6,3) NULL,
    DT_Admissao DATE NULL,
    DS_Motivo_Internacao VARCHAR(300) NULL,
    DS_Classificacao_Risco VARCHAR(20) NULL,
    TX_Historico_Anamnese TEXT NULL,
    TX_Evolucao_Clinica TEXT NULL,
    DT_Laudo DATE NULL,
    DS_Material_Analisado VARCHAR(150) NULL,
    TX_Diagnostico_Patologico TEXT NULL,
    TX_Protocolo_Medicamentoso TEXT NULL,
    DS_Metas_Tratamento VARCHAR(500) NULL,
    DS_Desfecho_Inferido VARCHAR(50) NULL,
    DT_Alta DATE NULL
);

INSERT INTO Paciente (
    DS_Especie, DS_Raca, DS_Sexo, DS_Idade_Referencia, DS_Chip, NR_Peso_Referencia, DT_Admissao, DS_Motivo_Internacao, DS_Classificacao_Risco, TX_Historico_Anamnese, TX_Evolucao_Clinica, DT_Laudo, DS_Material_Analisado, TX_Diagnostico_Patologico, TX_Protocolo_Medicamentoso, DS_Metas_Tratamento, DS_Desfecho_Inferido, DT_Alta
) VALUES (
    'Canina', 'Chow chow', 'Macho', '4 anos, 3 meses, 16 dias', NULL, 23.800, '2025-04-01', 'Pós operatório de Ablação de conduto auditivo + ablação de escroto + herniorrafia umbilical.', 'Amarelo', 'Paciente resgatado em 16/12, histórico de inflamação na orelha, miíase e múltiplas cirurgias auriculares prévias. Nova cirurgia em 01/04/2025 para ablação de conduto, ablação de escroto e herniorrafia umbilical. Imunoprofilaxia desatualizada, vermifugação em dia. Prurido, usa cone. Secreção purulenta ouvido esquerdo. Função renal limítrofe. Apetite voraz, normodipsia, constipação. Medicação prévia: Amoxicilina/clavulanato, Metronidazol.', '01-02/04/2025: Pós-operatório. Alerta, responsivo, deambulando. Bom controle álgico. Leve secreção serosanguinolenta em pontos cirúrgicos. Aceitou alimentação, sem êmese. Parâmetros vitais estáveis. ECG sinusal. POCUS s/ líquido livre. Feridas com pontos coaptados, secreção discreta a moderada em conduto auditivo. Urinou e se alimentou bem. Planejada alta para noite de 02/04.', '2025-04-09', 'Fragmentos cutâneos: região de bolsa escrotal e região de orelha esquerda.', 'A) Pele, bolsa escrotal: Dermatite linfoplasmocítica e neutrofílica acentuada e multifocal, associada a úlcera. B) Pele, orelha esquerda: Dermatite linfoplasmocítica multifocal e moderada e tricogranulomas.', 'Internação: Dipirona, Tramadol, Dexametasona, Metronidazol, Agemoxi, Gabapentina, Cerenia, Fluidoterapia Ringer Lactato. Alta (Oral): Dipirona, Cl. Tramadol, Predsim, Metronidazol, Gabapentina, Cerenia (SOS), Agemoxi CL.', 'Monitorar controle de dor, cicatrização de pontos e secreção. Avaliar possibilidade de alta. Alta no período noturno.', 'Alta Hospitalar', '2025-04-02'
);

INSERT INTO Paciente (
    DS_Especie, DS_Raca, DS_Sexo, DS_Idade_Referencia, DS_Chip, NR_Peso_Referencia, DT_Admissao, DS_Motivo_Internacao, DS_Classificacao_Risco, TX_Historico_Anamnese, TX_Evolucao_Clinica, DT_Laudo, DS_Material_Analisado, TX_Diagnostico_Patologico, TX_Protocolo_Medicamentoso, DS_Metas_Tratamento, DS_Desfecho_Inferido, DT_Alta
) VALUES (
    'Felina', 'SEM RAÇA DEFINIDA', 'Fêmea', '10 anos, 7 meses, 6 dias', NULL, 4.100, '2025-04-07', 'Dispnéia', 'VERMELHO', 'Paciente com histórico de respiração abdominal, veio para UTI por dispneia e cianose. FIV/FELV negativo. Perda de peso recente após mudança. Vacinação desatualizada.', 'Admitida em 07/04/2025 com dispneia e cianose, necessitando entubação e ventilação mecânica. Apresentou alta resistência pulmonar e hipotensão, necessitando de vasopressores (Noradrenalina). Hemogasometria indicou acidose respiratória. Devido à piora e prognóstico reservado, tutores optaram pela eutanásia em 08/04/2025.', '2025-04-07', 'Tórax (Raio-X)', 'Achados radiográficos relacionados a processo inflamatório de vias aéreas inferiores (broncopatia com possível componente infeccioso associado). Opacificação pulmonar difusa de padrão intersticial com paredes brônquicas mais evidentes e espessadas.', 'Clindamicina, Dipirona, Terbutalina, Acetilcisteína, Dexametasona, Ceftriaxona, Inalação com adrenalina, Metadona, Ringer Lactato, Propofol, Ketamina, Fentanil, Noradrenalina.', 'Suporte vital com ventilação mecânica e vasopressores, monitoramento contínuo.', 'Eutanásia', '2025-04-08'
);

INSERT INTO Paciente (
    DS_Especie, DS_Raca, DS_Sexo, DS_Idade_Referencia, DS_Chip, NR_Peso_Referencia, DT_Admissao, DS_Motivo_Internacao, DS_Classificacao_Risco, TX_Historico_Anamnese, TX_Evolucao_Clinica, DT_Laudo, DS_Material_Analisado, TX_Diagnostico_Patologico, TX_Protocolo_Medicamentoso, DS_Metas_Tratamento, DS_Desfecho_Inferido, DT_Alta
) VALUES (
    'Canina', 'Pastor maremano', 'Macho', '4 anos, 3 meses, 2 dias', NULL, 70.000, '2024-09-16', 'Pneumonia + Dor em MTE a esclarecer', 'AMARELO', 'Histórico de claudicação em MTD há 2 anos com neoformação não maligna (2022). Displasia coxofemoral diagnosticada em Março/2024, tratada com dieta e medicação para triglicerídeos/lama biliar (Ursacol, Bezafibrato, Ômega 3). Há 15 dias com dificuldade de locomoção, ferida em MPD, dor e hiporexia. Medicação prévia: Cefalexina, Tramadol. Desde 13/09/2024 não levanta, hiporexia, vômitos, sem defecar/urinar. Aumento abdominal e sensibilidade desde 12/09/2024. Vacinação V8 e Raiva (Ago/2023), vermifugação (Dez), ectoparasitas (Jan/Abr). Vive em sítio com 2 outros cães hígidos.', 'Admitido em 16/09/2024 prostrado, em oxigenioterapia, com dor em MTE. Diagnóstico de cetoacidose diabética e pneumonia. Inicialmente eupneico, depois piora do padrão respiratório com esforço expiratório e taquipneia, saturação 98% em O2 1,5L/min. Hematócrito caiu de 26% para 19-20%. Apresentou hipotensão (60 mmHg), iniciada prova de carga e vasopressores (noradrenalina). Em 18/09/2024, piora respiratória, necessitou intubação orotraqueal e ventilação mecânica. Realizada transfusão de concentrado de hemácias. Evoluiu com bradicardia, hipotensão importante, quadros de GEH, abaulamento abdominal e PCR não responsiva em 18/09/2024.', '2024-09-18', 'Punho e mão MTE e ...', 'Raio-X (12/09): Osteopatia hipertrófica em punhos e mãos, nódulo pulmonar em lobo caudal direito (suspeita neoplasia ou processo infeccioso/inflamatório), acentuada displasia coxofemoral esquerda. Citologia (18/09): MTE - Processo inflamatório crônico (osteomielite?); Linfonodo poplíteo - Linfadenite dermatopática. USG Abdômen (16/09): Hepatomegalia discreta com esteatose, lama biliar considerável, nefromegalia bilateral, prostatomegalia discreta, edema testicular e de bolsa escrotal.', 'Dipirona, Tramadol, Cetamina, Inalação com SF, Acetilcisteína, Ampicilina com Sulbactam (posteriormente Cefalosporina e Clindamicina), Bezafibrato, Cerenia, Lactulona, Sarcopen Vet, Manipulado (Ursacol + Bezafibrato + Ômega 3), Mirtazapina, Fluidoterapia (Ringer Lactato, Glicose), Insulina regular, Noradrenalina.', 'Monitorar fezes, POCUS, controle álgico, apetência, ACP, glicemia, hemogasometria, BHB, nível de consciência, hematócrito.', 'Óbito (PCR não responsiva)', '2024-09-18'
);

INSERT INTO Paciente (
    DS_Especie, DS_Raca, DS_Sexo, DS_Idade_Referencia, DS_Chip, NR_Peso_Referencia, DT_Admissao, DS_Motivo_Internacao, DS_Classificacao_Risco, TX_Historico_Anamnese, TX_Evolucao_Clinica, DT_Laudo, DS_Material_Analisado, TX_Diagnostico_Patologico, TX_Protocolo_Medicamentoso, DS_Metas_Tratamento, DS_Desfecho_Inferido, DT_Alta
) VALUES (
    'Canina', 'Pastor alemão', 'Fêmea', '11 anos, 4 meses, 11 dias', NULL, 35.000, '2025-05-12', 'P.O. Castração por Piometra + Herniorrafia + Miíase vulvar e oral', 'Amarelo', 'Paciente com histórico de cio com dilatação vulvar há 1,5 mês. Há 1 semana mais prostrada, com náusea. Exames prévios (10/05) mostraram ureia e creatinina elevadas. USG indicou piometra e hérnia. Miíase em vulva e boca identificada. Hiporexia, polidipsia, fezes pastosas/diarreicas, 2 episódios eméticos. Vacinação e vermifugação desatualizadas.', '12/05/2025 (Admissão): Admitida para P.O. de castração por piometra, herniorrafia e tratamento de miíase. Mucosas normocoradas, TPC 2s, discreta sensibilidade abdominal, lesão vulvar por miíase. Administrado Capstar. 13/05/2025 (Manhã): Prostrada, responsiva, ataxia em membros pélvicos, escape álgico abdominal (resgate analgésico realizado). Sem miíase ativa. TPC 3s, desidratação 6%. Um episódio emético, náusea. Aceitou pouca alimentação. Adipsia. Sondagem uretral de alívio (1L). 13/05/2025 (Tarde/Noite): Prostrada, responsiva. Padrão respiratório eupneico, mucosas levemente hipocoradas, TPC 2s. Álgia abdominal moderada em incisão e sensibilidade em coluna toracolombar. Resgate analgésico. Boa aceitação alimentar. Urinou em passeio, não defecou. Estável.', '2025-05-12', 'ECG, Hemograma, Ureia, Creatinina', 'ECG (12/05): Ritmo sinusal. Hemograma (10/05): Leucocitose (47.000/mm³) com neutrofilia e monocitose, proteína total aumentada (8,4 g/dl). Bioquímica (10/05 e 13/05): Ureia elevada (10/05: 180,0 mg/dL; 13/05: 240,00 mg/dL) e Creatinina elevada (10/05: 3,70 mg/dL; 13/05: 3,75 mg/dL), indicando azotemia.', 'Ampicilina com Sulbactam 22mg/Kg TID, Tramadol 3mg/Kg TID, Dipirona 25mg/Kg TID, Cetamina 0,5mg/Kg TID (Avaliar), Morfina 0,1mg/Kg TID (Avaliar), Dexametasona 0,1mg/Kg SID (Avaliar), Cerenia 0,1ml/Kg SID, Ondansetrona 1mg/Kg TID, Capstar 57mg (dose única na admissão), Cobavital 1 comprimido SID. Fluidoterapia: Ringer Lactato.', 'Monitorar hematócrito, controle de dor e náusea, estimular apetência, expectativa de função renal, estimular micção espontânea, monitorar feridas e presença de miíase. Avaliar alta.', 'Em tratamento/Acompanhamento', NULL
);

INSERT INTO Paciente (
    DS_Especie, DS_Raca, DS_Sexo, DS_Idade_Referencia, DS_Chip, NR_Peso_Referencia, DT_Admissao, DS_Motivo_Internacao, DS_Classificacao_Risco, TX_Historico_Anamnese, TX_Evolucao_Clinica, DT_Laudo, DS_Material_Analisado, TX_Diagnostico_Patologico, TX_Protocolo_Medicamentoso, DS_Metas_Tratamento, DS_Desfecho_Inferido, DT_Alta
) VALUES (
    'Canina', 'Yorkshire terrier', 'Fêmea', '9 anos, 11 meses, 11 dias', NULL, 3.900, '2024-10-28', 'Intoxicação por Tenoxicam', 'VERMELHO', 'Paciente castrada (piometra prévia), histórico de ixodidiose, sem acesso à rua. Tutores administraram Tenoxicam por engano para dor em patela. Apresentou prostração, hiporexia, vômito, fezes pastosas. Atendida por colega, medicada e indicada internação após exames (hemograma, bioquímico) e USG abdominal. Recusou alimentação e apresentou êmese após ingestão hídrica na internação anterior. Vacinação e vermifugação desatualizadas.', 'Admitida em 28/10/2024 prostrada, com redução do nível de consciência, acidemia e alterações eletrolíticas. Em 29/10, apresentou dispneia mista (SpO2 91%), crepitação pulmonar, necessitando oxigenioterapia e furosemida. Hemogasometria mostrou hipocalcemia e hipocalemia, com queda progressiva do hematócrito (de 22% na admissão para 19% e depois 13%), necessitando transfusão de concentrado de hemácias. Apresentou descarga nasal purulenta e refluxo sanguinolento por sonda nasogástrica. Em 30/10, alternou prostração e responsividade, evoluindo com episódio convulsivo (responsivo a diazepam), cianose, dispneia expiratória, necessitando intubação. Posteriormente, apresentou bradicardia não responsiva à atropina, evoluindo para PCR e óbito.', '2024-10-29', 'Sangue (Hemograma, ...', 'Hematócrito inicial 22%, evoluindo para 13%. Hemogasometria arterial (29/10): pH 7,109, PCO2 29,3 mmHg, PO2 79 mmHg, HCO3 9,3 mmol/L, BEecf -20 mmol/L, Na 171 mmol/L, K 3,2 mmol/L, iCa 1,09 mmol/L, Ht 17%. Evolução com hipocalcemia e hipocalemia. Hemograma (29/10): Eritrócitos 2,47 milhões/mm³, Hemoglobina 5,7 g/dL, Hematócrito 17,2%, Leucócitos 56,40 mil/mm³ com neutrofilia. Creatinina 8,94 mg/dL, Ureia 494,00 mg/dL.', 'Omeprazol, Sucralfato, Ampicilina com Sulbactam, Ondansetrona, Cerênia, Morfina, Dipirona, Tramadol, N-acetilcisteína, Kalium Vet, Furosemida, Bicarbonato, Diazepam (em crise convulsiva), Fluidoterapia (Ringer Lactato com reposição de KCl).', 'Avaliar passagem de SNG, Hmg + FR + albumina, USG abdominal, exames cardiológicos, monitorar hematócrito, DU, hemogasometria, SpO2 e padrão respiratório. Controle de dor e náusea, estimular apetência e micção espontânea, monitorar feridas.', 'Óbito', '2024-10-30'
);

