INSERT INTO Paciente (
    DS_Especie, DS_Raca, DS_Sexo, DS_Idade_Referencia, DS_Chip, NR_Peso_Referencia, DT_Admissao, DS_Motivo_Internacao, DS_Classificacao_Risco, TX_Historico_Anamnese, TX_Evolucao_Clinica, DT_Laudo, DS_Material_Analisado, TX_Diagnostico_Patologico, TX_Protocolo_Medicamentoso, DS_Metas_Tratamento, DS_Desfecho_Inferido, DT_Alta
) VALUES (
    'Canina', 'SEM RAÇA DEFINIDA', 'Fêmea', '15 anos, 3 meses, 14 dias', NULL, 6.250, '2025-05-06', 'Anemia/ Prostração á esclarecer', 'Amarelo', 'Paciente com histór...', 'Admitida em 06/05/2025 prostrada, com anemia (Ht 23%). Realizada transfusão de hemácias, Ht pós-transfusão 32%. Em 07/05, mais alerta, porém sonolenta, não deambula, com rigidez em membros torácicos e flacidez em pélvicos. Propriocepção reduzida em MMPP. Aceitou alimentação com auxílio. Sonda uretral com débito baixo. Apresentou bradicardia sinusal. Lesão ulcerada em ponta de orelha. Alta médica em 07/05/2025. Retornou em 15/05/2025 por prostração, hiporexia, ataxia. Apresentou creptação pulmonar, Ht 29%, Lactato 5,8 mmol/L. Solicitado USG abdominal.', '2025-05-07', 'Sangue (Hemograma, Bioquímica, Hemogasometria, Teste de Compatibilidade, Sorologia Erliquiose, Painel PCR), Urina tipo I, Ultrassonografia Abdominal.', 'Anemia (Ht admissão 23%,...', 'Internação (06-07/05):...', 'Acompanhar hematócr...', 'Alta médica (07/05/2025),...', '2025-05-07'
);

