INSERT INTO Paciente (
    DS_Especie, DS_Raca, DS_Sexo, DS_Idade_Referencia, DS_Chip, NR_Peso_Referencia, DT_Admissao, DS_Motivo_Internacao, DS_Classificacao_Risco, TX_Historico_Anamnese, TX_Evolucao_Clinica, DT_Laudo, DS_Material_Analisado, TX_Diagnostico_Patologico, TX_Protocolo_Medicamentoso, DS_Metas_Tratamento, DS_Desfecho_Inferido, DT_Alta
) VALUES (
    'Canina', 'Shih-Tzu', 'Macho', '9 anos, 6 meses, 8 dias', NULL, 10.600, '2023-04-28', 'P.O Lobectomia Pulmonar', NULL, 'Desde filhote com tutores. Vacinação desatualizada (não realizada em 2023), vermifugação em Nov. Controle de ectoparasitas. Passeios diários. Contato esporádico com outros animais. Alimenta-se de ração Satiety com arroz e legumes. Uso contínuo de colírios. Histórico de cirurgia ocular em Out/2022, seguida de tosse esporádica e achado de nódulo pulmonar. Castrado quando filhote. Babesiose subclínica diagnosticada, não tratada. Nega êmese, diarreia, síncope, convulsões. Chegou em emergência para lobectomia pulmonar.', '28/04/2023: Admitido pós-lobectomia pulmonar, agitado, em oxigenioterapia. Glicemia baixa (40 mg/dL) corrigida. Dreno torácico instalado. 29/04/2023: Taquipneia, esforço inspiratório, bexiga repleta, hipertensão. Realizada sondagem vesical, morfina e inalação, com melhora. Dreno com débito serosanguinolento. Retirado o dreno no final do dia. 30/04/2023: Alerta, responsivo, com algia importante, dificuldade para deitar, hipertensão. Adicionado miosan e cetamina com boa resposta. 01/05/2023: Ativo, deambulando, comendo bem, urinou espontaneamente, não defecou. Algia controlada com morfina e cetamina sendo desmamadas. Recebeu alta médica em 02/05/2023. Posteriormente, em 16/07/2024, nova internação por dispneia, inapetência e dor, com evolução para eutanásia no mesmo dia.', '2023-03-30', 'Tórax (Tomografia Computadorizada), Sangue (Hemograma, Bioquímica, Coagulograma), Ecocardiograma, Eletrocardiograma, Urina', 'Tomografia (30/03/2023): Neoformação pulmonar em lobo cranial esquerdo (8x9x7 cm), atelectasia, baço aumentado. Ecocardiograma (23/03/2023): Neoformação extra cardíaca em base cardíaca (8,4x7,5 cm), demais parâmetros normais. Hemograma (24/04/2023): Leucocitose acentuada (34.040/µL) com neutrofilia e neutrófilos tóxicos. Coagulograma (28/04/2023): Fibrinogênio aumentado (1430 mg/dL). Hemograma (02/05/2023): Leucocitose (29.200/µL) com neutrofilia, proteína total aumentada (8.6 g/dL).', 'Pré-operatório/Indução (28/04/2023): Metadona, Propofol, Midazolam, Cetamina, Isofluorano. Pós-operatório imediato: Dipirona, Dexametasona, Morfina. Internação (28/04-02/05/2023): Tramadol, Dipirona, Morfina, Cerenia, Ceftriaxona, Metronidazol, Omeprazol, Cetamina, Miosan, Gabapentina, Fluidoterapia RL. Alta (02/05/2023): Cerenia, Tramadol, Dipirona, Agemoxi CL, Metronidazol, Miosan, Gabapentina, Prednisolona. Internação posterior (16/07/2024): Analgesia e sedação.', 'Controle de dor, monitoramento do dreno torácico, função respiratória (desmame de O2), POCUS, hemogasometria, cicatrização da ferida cirúrgica, avaliação de alta.', 'Alta Hospitalar (02/05/2023 a...', '2024-07-16'
);

INSERT INTO Paciente (
    DS_Especie, DS_Raca, DS_Sexo, DS_Idade_Referencia, DS_Chip, NR_Peso_Referencia, DT_Admissao, DS_Motivo_Internacao, DS_Classificacao_Risco, TX_Historico_Anamnese, TX_Evolucao_Clinica, DT_Laudo, DS_Material_Analisado, TX_Diagnostico_Patologico, TX_Protocolo_Medicamentoso, DS_Metas_Tratamento, DS_Desfecho_Inferido, DT_Alta
) VALUES (
    'Canina', 'SEM RAÇA DEFINIDA', 'Macho', '10 anos, 9 meses, 24 dias', NULL, 19.000, '2025-04-24', 'P.O Lobectomia Pulmonar', 'Amarelo', 'Vacinação e vermifugação não atualizadas para o ano corrente, controle de ectoparasitas em dia. Passeios frequentes, contato esporádico com outros animais. Alimenta-se de ração Satiety com arroz e legumes. Uso contínuo de colírios. Histórico de cirurgia ocular em Out/2022, após a qual desenvolveu tosse esporádica e foi diagnosticado com nódulo pulmonar. Castrado quando filhote. Babesiose subclínica diagnosticada e não tratada. Nega êmese, diarreia, síncope, convulsões. Chegou em emergência para lobectomia pulmonar devido a tumor infiltrado.', '24/04/2025: Admitido em P.O. de lobectomia pulmonar, agitado, em oxigenioterapia (sonda nasal), vocalizando, mas sem sensibilidade dolorosa à palpação inicial. Glicemia na admissão de 208 mg/dL, Ht 35%. POCUS Ab/Tc negativos para líquido livre. Cirurgia com manipulação extensa devido ao tamanho do tumor (8cm), com fratura de costela. Queda de SpO2 transoperatória (80-83%) manejada. 25/04/2025: Alerta, responsivo, estável hemodinamicamente, eupneico. Aceitou alimento pastoso, urinou, não defecou. Edema em maxila esquerda. Hemogasometria controle para hipocalemia. 26/04/2025: Alerta, bom controle álgico, melhora do edema facial, diminuição da secreção serosanguinolenta oral. Ht 28%, Glicemia 80. Aceitou alimentação líquida. Urinou, não defecou. Liberado para casa em 26/04/2025 com orientações e prescrição.', NULL, 'Hemogasometria, Hematócrito, Glicemia, POCUS (abdominal e torácico), ECG.', 'Pós-operatório de lobectomia pulmonar. Edema em maxila esquerda. Discreta hipocalemia (em 25/04). Queda de hematócrito (de 35% para 28%) esperada pós-cirúrgico. ECG: Ritmo sinusal.', 'Internação (24/04-26/04): Ceftriaxona, Metronidazol, Dipirona, Tramadol, Dexametasona, Inalação com adrenalina, Metadona (avaliar, não realizado), Cetamina (avaliar, não avaliado), Inalação com SF, Cerenia (adicionado em 25/04). Fluidoterapia: Ringer Lactato. Alta (26/04): Dipirona, Cloridrato de Tramadol, Prednisolona, Metronidazol, Zinnat, Inalação com soro fisiológico.', 'Avaliar alta, coletar exames controle (Hemograma, albumina, ureia, creatinina), monitorar conforto álgico, estimular apetência, monitorar ferida cirúrgica.', 'Alta Hospitalar', '2025-04-26'
);

INSERT INTO Paciente (
    DS_Especie, DS_Raca, DS_Sexo, DS_Idade_Referencia, DS_Chip, NR_Peso_Referencia, DT_Admissao, DS_Motivo_Internacao, DS_Classificacao_Risco, TX_Historico_Anamnese, TX_Evolucao_Clinica, DT_Laudo, DS_Material_Analisado, TX_Diagnostico_Patologico, TX_Protocolo_Medicamentoso, DS_Metas_Tratamento, DS_Desfecho_Inferido, DT_Alta
) VALUES (
    'Canina', 'Yorkshire terrier', 'Fêmea', '14 anos, 6 meses, 15 dias', '981020002574985', 2.100, '2025-04-04', 'Edema pulmonar cardiogênico', 'Amarelo', 'Paciente com histórico de cardiopatia, pneumopatia, e sensibilidade cutânea. Cirurgia de OH por piometra prévia com infecção pós-operatória. Crise convulsiva no início do ano. Tosse e dispneia recorrentes, tratada com Seretide. Piora da tosse há dois dias, levando à internação e posterior transferência para UTI por edema pulmonar severo. Medicações de uso contínuo: Pimobendan, Espironolactona, Codeína, Gabapentina, Trazodona, Seretide. Vacinação atualizada, sem controle de ectoparasitas recente. Alimentação: Royal Canin Hipoalergênica e sachê de salmão.', '04/04: Admitida em UTI com edema pulmonar severo, taquicardia, taquipneia, hipotensão inicial (90 mmHg) e desidratação. Iniciada infusão de nitroprussiato e dobutamina (posteriormente desmamada). Apresentou agitação, necessitando butorfanol. Saturação inicial 90-92% em oxigênio. 05/04: Alerta, responsiva, PA entre 140-150mmHg com nitroprussiato (1,0 mcg/kg/min). Cortina de linhas B em hemitórax esquerdo e >6 linhas B em hemitórax direito. Realizado ecocardiograma. Mantida em O2 (0,5L/min), saturação 95%. 06/04: Alerta, eupneica, fora do oxigênio com saturação 96%. Linhas B em POCUS melhoraram (até 3 linhas). Defecou. 07/04: Alerta, deambulando, eupneica na maior parte do tempo, mas com dispneia e cianose à manipulação. Saturação 94-96% sem O2. Borborigmos aumentados, distensão abdominal por aerofagia. Administrada Trazodona para agitação. Planejada alta médica.', '2025-04-03', 'Raio-X de Tórax, Ecocardiograma, Hemograma, Bioquímica (Ureia, Creatinina, Fósforo, Potássio), Hemogasometria.', 'Raio-X (03/04): Cardiomegalia, traqueomalacia/broncomalácia, hepatomegalia, processo degenerativo em coluna. Ecocardiograma (05/04): Alteração pulmonar importante (não especificado no laudo, mas mencionado na evolução ). Hemograma (04/04): Eritrócitos e Hemoglobina no limite inferior ou discretamente abaixo, Proteína total aumentada (8.20 g/dL). Bioquímica (04/04): Ureia 96 mg/dL (aumentada), Creatinina 1,34 mg/dL (normal), Fósforo 8,94 mg/dL (aumentado, amostra hemolisada), Potássio 5,60 mEq/L (discretamente aumentado, amostra hemolisada). Hemogasometria (Admissão): pH 7,320, PCO2 59,4 mmHg, PO2 41 mmHg, HCO3 30,6 mmol/L, BEecf 4 mmol/L, Lactato 6,2 mmol/L.', 'Admissão/Internação: Nitroprussiato, Dobutamina, Butorfanol, Furosemida, Ampicilina + Sulbactam, Inalação com SF (+ Dexametasona inicialmente, depois SF puro), Terbutalina, Hidrocortisona, Acetilcisteína, Pimobendan, Espironolactona, Codeína, Gabapentina, Trazodona, Sildenafil, Prednisolona. Fluidoterapia Ringer Lactato. Alta: Dipirona gotas, Trazodona, Synulox, Acetilcisteína, Sildenafil, Prednisolona, Inalação com SF, e manter medicações de uso contínuo (Pimobendan, Espironolactona, Seretide, Gabapentina, Codeína).', 'Controle álgico, monitorar POCUS (linhas-B), desmame de nitroprussiato e oxigênio, coletar hemogasometria controle, avaliação de alta médica, estimular apetência, monitorar micção, manipular o mínimo possível.', 'Alta Hospitalar', '2025-04-07'
);

INSERT INTO Paciente (
    DS_Especie, DS_Raca, DS_Sexo, DS_Idade_Referencia, DS_Chip, NR_Peso_Referencia, DT_Admissao, DS_Motivo_Internacao, DS_Classificacao_Risco, TX_Historico_Anamnese, TX_Evolucao_Clinica, DT_Laudo, DS_Material_Analisado, TX_Diagnostico_Patologico, TX_Protocolo_Medicamentoso, DS_Metas_Tratamento, DS_Desfecho_Inferido, DT_Alta
) VALUES (
    'Canina', 'SEM RAÇA DEFINIDA', 'Macho', '13 anos, 7 meses, 25 dias', NULL, 11.000, '2024-07-10', 'P.O Adrenalectomia Direita', 'Amarelo', 'Comprado filhote, próstata aumentada, sem outras cirurgias prévias. Restrição alimentar (ração light e sachê). Polifagia há 4-5 meses. Fezes normais a enegrecidas, ocasionalmente ressecadas. Urina normal. Episódio de vômito com espuma e ração no dia da admissão após medicação. Hipertensão diagnosticada. Em uso de Ograx-3, Luftal, Anlodipino. Vacina V10 atualizada, raiva desatualizada. Vermifugação endo e ecto desatualizada. Histórico de pancreatite. Exames prévios (USG, ECG, coagulograma, raio-x, TC, hemograma) realizados.', '10/07/2024: Admitido após adrenalectomia direita, alerta, responsivo/reativo, com dor importante (10/24), melhorou com metadona e cetamina (2/24). Sialorreia, mucosas normocoradas, TPC 2s, desidratação 5%, abdômen tenso. PAS inicial 220 mmHg, depois 150 mmHg. Hemogasometria na admissão com acidemia metabólica (pH 7,145, BEecf -15, HCO3 13,5) e Ht 48%. 11/07/2024: Manteve-se alerta, com comportamento protetivo. Sonda uretral retirada, não urinou ou defecou no período da manhã (plantão noturno), mas urinou espontaneamente durante o dia. Aceitou pouca alimentação e água. Ferida cirúrgica íntegra com discreta secreção inflamatória. 12/07/2024: Apático, mas responsivo. Bom controle de dor. Não aceitou alimentação. Urinou espontaneamente. Ht 39%, Glicemia 115mg/dl. Hemograma e albumina coletados, aguardando ACTH. Alta médica em 12/07/2024.', '2024-07-13', 'Sangue (Hemograma, Bioquímica: Ureia, Creatinina, Albumina; Hemogasometria, Teste de estimulação por ACTH).', 'Hemogasometria admissional (10/07/2024): Acidemia metabólica (pH 7,145, HCO3 13,5 mmol/L, BEecf -15 mmol/L), Ht 48%. Hemograma (12/07/2024): Ht 36,6%, Leucócitos 14.000/mm³ (Segmentados 85%, Linfócitos 4%), Plaquetas 270 mil/mm³. Albumina (12/07/2024): 2,70 g/dl. Ureia (13/07/2024): 21,00 mg/dl. Creatinina (13/07/2024): 1,01 mg/dl.', 'Internação (10/07-12/07): Ampicilina + Sulbactam (22 mg/kg TID), Dipirona (25 mg/kg TID ou 35 mg/kg TID conforme boletins), Tramadol (3 mg/kg TID), Cetamina (0,5 mg/kg TID avaliar/resgate), Anlodipino (0,1 mg/kg SID), Dexametasona (0,15 mg/kg SID), Metadona (0,1 mg/kg na admissão), Fluidoterapia Ringer Lactato (taxas variando, ~60 ml/kg/dia e depois ~21,5 ml/h).', 'Monitorar POCUS, aguardar resultado do teste de estimulação por ACTH, controle álgico, coletar hemograma + albumina, avaliar alta médica.', 'Alta Hospitalar', '2024-07-12'
);

INSERT INTO Paciente (
    DS_Especie, DS_Raca, DS_Sexo, DS_Idade_Referencia, DS_Chip, NR_Peso_Referencia, DT_Admissao, DS_Motivo_Internacao, DS_Classificacao_Risco, TX_Historico_Anamnese, TX_Evolucao_Clinica, DT_Laudo, DS_Material_Analisado, TX_Diagnostico_Patologico, TX_Protocolo_Medicamentoso, DS_Metas_Tratamento, DS_Desfecho_Inferido, DT_Alta
) VALUES (
    'Canina', 'Welsh corgi', 'Macho', '12 anos, 3 meses, 25 dias', NULL, 18.000, '2025-05-11', 'Convulsão', 'Amarelo', 'Histórico de sarcoma de tecidos moles em MTE (internação anterior em Dez/2024 para controle álgico e ressonância). Em uso de Fenobarbital, Gabapentina, Hepvet, Pressat, Levotiroxina. Tutora relata episódios de crise epiléptica, com o último ocorrendo em 10/05/2025. Vacinação e vermifugação em dia. Alimentação com ração úmida e seca. Nega alergias.', '11/05/2025: Admitido por quadro de convulsão. Alerta, responsivo, defensivo. Claudicação em MTE, sensibilidade articular e toracolombar. Recusou alimentação. Apresentou três crises epilépticas (focal para tônico-clônica generalizada), controladas com Diazepam. Cianose de língua durante manipulação, necessitou oxigenioterapia. Sonda uretral para alívio. Hipertensão controlada com medicação. 12/05/2025: Alerta, responsivo, defensivo. Confortável, dormindo. Deambula com auxílio, ataxia em MM PP, claudicação MTE. Abdominalgia mesogástrica, algia em MTE e coluna toracolombar. Aceitou alimentação com apetite no início do plantão, jejum para ressonância a partir das 23h. Urinou via sonda (hematúria). Sem êmese. Saturação 95% sem oxigênio. 13/05/2025 (manhã): Prostrado, responsivo, vocalizou. Sem crises epilépticas. Alimentou-se de forma assistida, oligodipsia. Urinou via sonda, não defecou. Tutores optaram por eutanásia às 9h30.', '2025-05-07', 'Sangue (Hemograma, Colesterol, Triglicerídeos), ECG, POCUS.', 'Hemograma (07/05/2025): Eritrograma dentro dos valores de referência, leucócitos 7.100/mm3 (dentro da normalidade), plaquetas 384.000/mm3. Colesterol 249 mg/dL, Triglicérides 137 mg/dL (12/05/2025). ECG (11/05 e 12/05): Ritmo sinusal, sopro mitral grau II/IV. POCUS (11/05 e 12/05): Sem líquido livre em cavidades, bexiga com moderada repleção.', 'Internação (Maio/2025): Fluidoterapia Ringer Lactato, Diazepam (para crises), Anlodipino (Pressat), Fenobarbital, Gabapentina, Metadona, Ondansetrona, Dipirona, Hepvet, Levotiroxina, Oxigenioterapia conforme necessidade.', 'Controle de crises epilépticas, controle álgico, monitoramento hemodinâmico e respiratório, preparo para ressonância magnética, avaliação de alta. Posteriormente, eutanásia por decisão do tutor.', 'Eutanásia', '2025-05-13'
);

INSERT INTO Paciente (
    DS_Especie, DS_Raca, DS_Sexo, DS_Idade_Referencia, DS_Chip, NR_Peso_Referencia, DT_Admissao, DS_Motivo_Internacao, DS_Classificacao_Risco, TX_Historico_Anamnese, TX_Evolucao_Clinica, DT_Laudo, DS_Material_Analisado, TX_Diagnostico_Patologico, TX_Protocolo_Medicamentoso, DS_Metas_Tratamento, DS_Desfecho_Inferido, DT_Alta
) VALUES (
    'Canina', 'SEM RAÇA DEFINIDA', 'Macho', '12 anos, 2 meses, 15 dias', NULL, 41.150, '2025-03-16', 'Gastrite', NULL, 'Paciente encaminhado para internação devido a gastrite. Apresenta megaesôfago significativo em radiografia, com suspeita de pneumonia incipiente. Aumento da tireoide observado em palpação e radiografia. Histórico de excesso de peso e lentidão, mas sem alterações dermatológicas que confirmassem hipotireoidismo. Reside em sítio, com possível exposição a carrapatos.', '16/03: Admitido com quadro de gastrite, diagnosticado com megaesôfago e suspeita de pneumonia. 17/03: Apresentou piora no hemograma, anemia não regenerativa. Considerada aplicação de EPO. Solicitada pesquisa de hemoparasitas. 18/03: Alimentou-se sem regurgitação, hematócrito necessitando melhora. 19/03: Alerta, responsivo, sem alterações em POCUS torácico/abdominal. Retornou para fluidoterapia devido a sódio em 147. Sem êmese/regurgitação com manejo para megaesôfago. Ht 19%, realizada transfusão de concentrado de hemácias (duas bolsas). 20/03: Aguardando teste de Babesia. Discutida possível relação da anemia com espessamento focal de piloro. 21/03: Estável, responsivo, programada alta médica.', '2025-03-19', 'Sangue (Hemograma, Contagem de Reticulócitos, T4 Livre, T4 Total, PCR para Babesia, Sorologia para Erliquiose)', 'Megaesôfago. Anemia não regenerativa (Ht 17/03: 23,5%; Ht 18/03: ?; Ht 19/03: 19%, pós-1ª bolsa transfusão 24%, necessitando 2ª bolsa). T4 Livre (12/04/2025): em andamento. T4 Total (10/05/2025): 1,76 µg/dL (ref: 1,25-3,90). Reticulócitos (12/04/2025): 0,104 (não regenerativa); (24/04/2025): 1,742 (regenerativa). Sorologia Erliquiose (18/03/2025): 1:40 (negativo/inespecífico). PCR Babesia (18/03/2025): Não detectado.', 'Fluidoterapia (Ringer Lactato), manejo para megaesôfago, Eritropoetina (EPO), transfusão de concentrado de hemácias. Medicação de alta: Gabapentina, Dipirona, Sucralfato, Amoxicilina + Clavulanato, Sildenafil, Predsin, Apevitin BC, Cerenia.', 'Estabilizar quadro de gastrite, investigar e tratar causa do megaesôfago e da anemia. Monitorar resposta à transfusão e EPO. Avaliar função tireoidiana e pesquisa de hemoparasitas. Alta médica.', 'Alta Hospitalar', '2025-03-21'
);

INSERT INTO Paciente (
    DS_Especie, DS_Raca, DS_Sexo, DS_Idade_Referencia, DS_Chip, NR_Peso_Referencia, DT_Admissao, DS_Motivo_Internacao, DS_Classificacao_Risco, TX_Historico_Anamnese, TX_Evolucao_Clinica, DT_Laudo, DS_Material_Analisado, TX_Diagnostico_Patologico, TX_Protocolo_Medicamentoso, DS_Metas_Tratamento, DS_Desfecho_Inferido, DT_Alta
) VALUES (
    'Canina', 'Dachshund pelo curto', 'Fêmea', '8 anos, 5 meses, 15 dias', NULL, 6.500, '2025-05-16', 'P.O. Celiotomia exploratória (obstrução intestinal por corpo estranho)', 'Amarelo', 'Adquirida há menos de um mês, doação. Castrada com ~1 ano. Tratamento periodontal e retirada de verruga há ~2 anos. Gastrite em Out/2023 com boa resposta, mas manteve edema em duodeno e aumento de enzimas hepáticas. Tentativa de tratamento com fitoterápico (Pró fígado) em Jan/25 causou fezes pastosas. Consulta gastro e troca de ração sem aceitação, retornou à alimentação habitual. Quarta-feira (14/05/2025) iniciou vômitos (alimentar, depois aquoso/espuma), aquezia, apatia e desconforto. Quinta-feira (15/05/2025) prostrada, aceitou pouca alimentação, continuou vomitando. Tremores à noite, medicada com Nolvagina, sucralfilm, Vonau; vomitou tudo. Madrugada com mais vômitos e tremores, levada ao veterinário. Manhã de 16/05/2025 um pouco melhor, levada para fluidoterapia, exames (hemograma, USG). No USG, suspeita de corpo estranho em duodeno, encaminhada para cirurgia.', '16/05/2025: Chegou para cirurgia, apresentando hematêmese na recepção. Glicemia 51mg/dL. Realizada sondagem orogástrica (360ml conteúdo sanguinolento) e celiotomia exploratória com enterotomia para remoção de corpo estranho (pedaço de semente/castanha) em duodeno. Estômago e intestino delgado congestos com alteração de coloração em serosa. Pós-cirúrgico imediato: Ht 70%, Glicemia 61mg/dL, Lactato 3.5mmol/L, hipotermia. 17/05/2025 (madrugada/manhã): Alerta, dócil, confortável. Mucosas normocoradas e secas, TPC 3s, desidratação 6%. Abdominalgia à palpação (em analgesia). Jejum de 6h pós-cirúrgico, depois alimentação líquida aceita. Hipoglicemias (61, depois 59mg/dL) corrigidas com bolus de glicose IV e alimentação. Ht caiu para 60%. Hipocalemia (K 2,9 -> 3,7 mmol/L). ECG sinusal.', '2025-05-16', 'Sangue (Albumina, Hemograma, Bioquímica - inferido pelos achados de Ht, Glicemia, Lactato, K)', 'Pós-operatório de enterotomia por corpo estranho. Hipoglicemia recorrente. Hipocalemia em melhora. Anemia relativa (Ht caiu de 70% para 60%). Desidratação 6%. Albumina 3,74 g/dl (normal).', 'Internação: Fluidoterapia (Glicofisiológica ou Ringer Lactato com Glicose e KCl), Dipirona, Tramadol, Cerenia, Ampicilina com Sulbactam, Metadona (resgate álgico), Omeprazol, Sucralfato. Anestesia: Metadona, Propofol, Midazolam, Cetamina, Lidocaína, Fentanil, Isoflurano. Bolus de glicose IV.', 'Controle da dor, monitoramento de glicemia, hematócrito e eletrólitos (especialmente potássio), hidratação, manejo alimentar pós-operatório (jejum inicial, depois dieta líquida fracionada), monitorar micção e defecação.', 'Em tratamento/Internada', NULL
);

INSERT INTO Paciente (
    DS_Especie, DS_Raca, DS_Sexo, DS_Idade_Referencia, DS_Chip, NR_Peso_Referencia, DT_Admissao, DS_Motivo_Internacao, DS_Classificacao_Risco, TX_Historico_Anamnese, TX_Evolucao_Clinica, DT_Laudo, DS_Material_Analisado, TX_Diagnostico_Patologico, TX_Protocolo_Medicamentoso, DS_Metas_Tratamento, DS_Desfecho_Inferido, DT_Alta
) VALUES (
    'Canina', 'Scottish terrier', 'Fêmea', '2 anos, 11 meses, 5 dias', NULL, 9.300, '2025-05-10', 'P.O laparotomia para retirada de corpo estranho', 'Amarelo', 'Desde filhote com a tutora. Oriunda de Recife, morou na Suíça. Vacinação, vermifugação e controle de ectoparasitas atualizados. Castrada aos 3 meses. No dia anterior à admissão (09/05/2025) apresentou anorexia, 5 episódios eméticos de espuma branca, aquezia, apatia e desconforto. Em 10/05/2025, levada a colega que constatou corpo estranho intestinal e indicou cirurgia, realizada no mesmo dia. Objeto de borracha (aprox. 4cm) foi "ordenhado" pelo intestino, sem necessidade de enterotomia. Alimentação: Royal Canin Gastrointestinal Low Fat.', '10/05/2025 (Admissão P.O.): Chegou deambulando, alerta e responsiva. Mucosas normocoradas, TPC 3s. Curativo cirúrgico íntegro. Aceitou alimentação (Gastro low fat úmida) e água. Glicemia 153 mg/dL, Ht 48%. 11/05/2025 (Manhã - Noturno All Care): Alerta, dócil, confortável. Mucosas normocoradas, TPC 2s. Sem abdominalgia. Aceitou alimentação com pouco apetite, não urinou, aquezia. 11/05/2025 (Tarde - Diurno All Care): Alerta, responsiva. Discreta algia abdominal pela manhã, controlada com analgesia. Aceitou alimentação com bom apetite. Urinou sem alterações. Estável. AB POCUS: discreta quantidade de líquido livre abdominal não drenável.', NULL, 'POCUS (abdominal e torácico), ECG, Hematócrito, Glicemia.', 'Pós-operatório de laparotomia para retirada de corpo estranho. POCUS admissão: Ínfima quantidade de líquido livre em janela cistocólica. POCUS 11/05 (manhã): Sem efusão pleural/pericárdica, sem linhas B. Bexiga com moderada repleção. POCUS 11/05 (tarde): Discreta quantidade de líquido livre abdominal não drenável; sem efusão pleural/pericárdica, linhas A. ECG: Ritmo sinusal. Ht admissão: 48%. Glicemia admissão: 153 mg/dL.', 'Anestesia (10/05): Cefalosporina (transoperatório). Internação (10/05-11/05): Fluidoterapia Ringer Lactato, Dipirona, Tramadol, Cerenia. Foi discutido adicionar Ampicilina com Sulbactam, mas mantido o Cef (realizado no transoperatório).', 'Controle álgico, monitorar ferida cirúrgica, retorno da função gastrointestinal (micção e defecação), avaliação de apetite e hidratação. Alta médica assim que estável.', 'Alta Hospitalar', '2025-05-11'
);

INSERT INTO Paciente (
    DS_Especie, DS_Raca, DS_Sexo, DS_Idade_Referencia, DS_Chip, NR_Peso_Referencia, DT_Admissao, DS_Motivo_Internacao, DS_Classificacao_Risco, TX_Historico_Anamnese, TX_Evolucao_Clinica, DT_Laudo, DS_Material_Analisado, TX_Diagnostico_Patologico, TX_Protocolo_Medicamentoso, DS_Metas_Tratamento, DS_Desfecho_Inferido, DT_Alta
) VALUES (
    'Felina', 'SEM RAÇA DEFINIDA', 'Fêmea', '2 anos, 7 meses, 4 dias', NULL, 3.100, '2024-07-10', 'P.O Bypass Ureteral Subcutaneo', 'Amarelo', 'Adotada com ~11 meses, FIV/FELV negativa, sem acesso à rua. Histórico de tríade felina no ano anterior, com achado de cálculo em ureter esquerdo, resultando em ureterostomia. Neste ano, check-up revelou cálculo em ureter direito, sem sinais clínicos. Normorexia, normodipsia, normoúria, normoquesia. Nega comorbidades ou restrições. Encaminhada para P.O. de Bypass Ureteral Subcutâneo.', '10/07/2024 (Admissão P.O.): Admitida em retorno anestésico, bom controle álgico. Parâmetros estáveis (FC 116bpm, FR 28mpm, PAS 110mmHg, T 37°C). Mucosas normocoradas, hidratada, TPC 2s. ECG: Ritmo Sinusal. Hemogasometria admissional: pH 7,206, PCO2 35,5 mmHg, HCO3 14,1 mmol/L, BEecf -14 mmol/L, K 3,3 mmol/L, Glicemia 218 mg/dL, Ht 39%. 11/07/2024 (Manhã): Alerta, responsiva, deambulando. Parâmetros estáveis, controle álgico adequado. Não aceitou alimentação espontaneamente, ingeriu pouca água. Tutoras vieram e retiraram a paciente (alta não dada) para transferência a outro local.', NULL, 'Hemogasometria', 'Pós-operatório de Bypass Ureteral Subcutâneo. Hemogasometria admissional com acidemia metabólica leve e hiperglicemia.', 'Fluidoterapia: Ringer Lactato + Complexo B + KCL. Analgesia: Dipirona 25mg/kg TID, Tramadol 2mg/kg TID. Antibioticoterapia: Ampicilina com Sulbactam 30mg/kg TID. Outros: Mirtazapina 1/4 comp SID, Cerenia 0,1ml/kg SID, Omeprazol 1mg/kg BID.', 'Monitorar controle álgico, retorno da função gastrointestinal e urinária, apetite. Acompanhar parâmetros hemodinâmicos.', 'Transf...', '2024-07-11'
);